class BoundedReader(io.RawIOBase):
    """Byte-budget view over a decompressed stream (plain CSV also counts)."""

    def __init__(self, source, budget):
        self.source = source
        self.budget = budget

    def readable(self):
        return True

    def readinto(self, buffer):
        block = self.source.read(len(buffer))
        if not block:
            return 0
        self.budget[0] -= len(block)
        if self.budget[0] < 0:
            raise CaptureError('decompressed byte budget')
        buffer[:len(block)] = block
        return len(block)

    def close(self):
        try:
            self.source.close()
        except AttributeError:
            pass
        super().close()


def byte_stream(chunks, encoding):
    """Decode base64 chunks and return a raw (possibly compressed) byte stream."""
    blocks = [decode64(text, CaptureError) for text in chunks]
    blob = b''.join(blocks)
    if encoding == 'zstd':
        try:
            complete_frames(blob)
        except zstd.ZstdError as exc:
            raise CaptureError('invalid Zstandard frame') from exc
        reader = zstd.ZstdDecompressor(
            max_window_size=WINDOW_LIMIT).stream_reader(io.BytesIO(blob),
                                                        read_across_frames=True)
        return reader, len(blob)
    del blocks
    return io.BytesIO(blob), len(blob)


def logical_rows(stream, budget):
    """Yield logical CSV records of one UTF-8 stream."""
    bounded = io.BufferedReader(BoundedReader(stream, budget))
    text = io.TextIOWrapper(bounded, encoding='utf-8', newline='')
    return csv.reader(text, strict=True), text


